// Pre-checkout personalized product preview (selected favorite + product -> watermarked mockup, or an explicit status) and the server-side cart
// (PUT /lines persistence across polling, restore and refresh). In-memory store, fake generator and a recording renderer; the scene DESCRIPTIONS are the real manifests.
// Nothing is generated by a model, paid, ordered or sent to a lab.

import { describe, it, expect, vi } from 'vitest'
import sharp from 'sharp'
import { createSession, startBatch, setLines, getSessionView, getBatchView, restoreSession, deleteSessionNow, type GiftDeps } from './service'
import { memoryGiftStore } from './store'
import { selectArtwork } from './compose'
import { getProductPreview } from './product-preview'
import { realSceneRenderer } from './mockup-real'
import { allProducts, getProduct } from '../print/catalog'
import type { SceneRenderer } from './scenes'
import type { MockupRenderer } from './mockup'
process.env.GIFT_NO_SCENE_PRESENTATION = 'calibrated'   // these tests cover the LEGACY template renderer for products without a scene (off by default); the default artwork-only presentation has its own tests in no-scene-presentation.test.ts

const U1 = '10000000-0000-4000-8000-000000000001', U2 = '20000000-0000-4000-8000-000000000002'

function rig() {
  const store = memoryGiftStore(), files = new Map<string, Buffer>()
  const state = { rev: 'scene-rev-1', sceneFail: false }
  const generate = vi.fn(async (i: { aspect: string }) => {
    const [w, h] = i.aspect.split(':').map(Number)
    return { imageB64: (await sharp({ create: { width: 512 * w, height: 512 * h, channels: 3, background: '#3a6' } }).png().toBuffer()).toString('base64') }
  })
  const watermark = vi.fn(async (b64: string) => sharp(Buffer.from(b64, 'base64')).jpeg().toBuffer())
  const sceneRender = vi.fn(async (i: { sceneId: string; productFamily: string; artworkId: string; artwork: Buffer }) => {
    if (state.sceneFail) throw new Error('scene boom')
    return { png: await sharp({ create: { width: 1254, height: 1254, channels: 3, background: '#789' } }).png().toBuffer(), width: 1254, height: 1254, templateRevision: state.rev, visualizationKey: 'svk', metadata: { fit: 'exact-composition' } }
  })
  const scenes: SceneRenderer = { describe: id => realSceneRenderer.describe(id), revision: vi.fn(async () => state.rev), render: sceneRender }
  const render = vi.fn(async (i: { sku: string }) => {
    const p = allProducts().find(x => x.sku === i.sku)!
    return { png: await sharp({ create: { width: 300, height: 200, channels: 3, background: '#cba' } }).png().toBuffer(), width: 300, height: 200, visualizationKey: 'vk', configuration: { sku: p.sku, requiredPx: { w: p.requirements.finalPx.w, h: p.requirements.finalPx.h } }, crop: null }
  })
  const mockup: MockupRenderer = { revision: vi.fn(async () => 'cal-rev-1'), render, scenes }
  const deps: GiftDeps = {
    store, generate, watermark, compose: vi.fn() as any, mockup,
    storage: {
      put: async (p, b) => { files.set(p, b) }, get: async p => files.get(p) ?? null, remove: vi.fn(async (ps: string[]) => { for (const p of ps) files.delete(p) }),
      signedUrl: async (p, s) => (files.has(p) ? `https://signed.test/${p}?ttl=${s}` : null), list: async prefix => [...files.keys()].filter(k => k.startsWith(prefix)),
    },
    analyze: async () => ({ status: 'supported', series: 'portraits', peopleCount: null }), kick: vi.fn(async () => ({})),
  } as GiftDeps
  return { deps, store, files, generate, watermark, sceneRender, render, state, scenes }
}
const photo = async () => (await sharp({ create: { width: 600, height: 600, channels: 3, background: '#a33' } }).jpeg().toBuffer()).toString('base64')
async function withFavorite(r: ReturnType<typeof rig>, user = U1) {
  const v = await createSession(r.deps, { userId: user, imageB64: await photo() })
  const b = await startBatch(r.deps, user, v.sessionId, { idempotencyKey: 'idem-key-1' })
  const fav = b.batch.previews[0].previewId
  await selectArtwork(r.deps, user, v.sessionId, fav)
  return { sid: v.sessionId, fav }
}
const previewFiles = (r: ReturnType<typeof rig>) => [...r.files.keys()].filter(k => k.includes('/product-previews/'))

describe('pre-checkout product preview', () => {
  it('shows the favorite in a square canvas through the photographic scene: watermarked, signed, nothing created', async () => {
    const r = rig(); const { sid, fav } = await withFavorite(r)
    const before = JSON.stringify(await getSessionView(r.deps, U1, sid)), compBefore = r.store.compositions.length, marks = r.watermark.mock.calls.length, gens = r.generate.mock.calls.length
    const v = await getProductPreview(r.deps, U1, sid, 'canvas:8x8')
    expect(v).toMatchObject({ contractVersion: 1, status: 'ready', productId: 'canvas:8x8', sku: 'GLOBAL-CAN-8X8', favoriteId: fav, renderer: 'scene', sceneId: 'gallery-canvas-square', watermarked: true, productionPrintFile: false, purchaseAuthorization: false, cached: false, width: 1254, height: 1254 })
    expect((v as any).url).toMatch(/^https:\/\/signed\.test\/gift\/.+\/product-previews\/canvas_8x8-[0-9a-f]{16}\.jpg/)
    expect(r.watermark.mock.calls.length).toBe(marks + 1)                                          // marked, always (nothing here is paid)
    expect(r.sceneRender.mock.calls[0][0]).toMatchObject({ sceneId: 'gallery-canvas-square', productFamily: 'canvas', artworkId: fav })
    expect(previewFiles(r)).toHaveLength(1); expect(r.store.compositions.length).toBe(compBefore)         // no composition
    expect(r.generate.mock.calls.length).toBe(gens)                                                  // no generation
    expect(JSON.stringify(await getSessionView(r.deps, U1, sid))).toBe(before)                      // session, favorite, approvals, corrections, entitlement: untouched
    expect([...r.files.keys()].every(k => !k.includes('/product-previews/') || k.endsWith('.jpg'))).toBe(true)
  })

  it('gives the scene renderer a picture shaped to the opening from the favorite, never the stored master itself', async () => {
    const r = rig(); const { sid } = await withFavorite(r); await getProductPreview(r.deps, U1, sid, 'canvas:8x8')
    const given = r.sceneRender.mock.calls[0][0].artwork, masters = [...r.files.entries()].filter(([k]) => k.includes('/masters/')).map(([, b]) => b)
    expect(masters.some(m => m.equals(given))).toBe(false)
    const m = await sharp(given).metadata(); expect(Math.abs(m.width! / m.height! / realSceneRenderer.describe('gallery-canvas-square').inputAspect - 1)).toBeLessThanOrEqual(1 / m.width! + 1 / m.height!)
  })

  it('an unchanged identity re-signs the stored preview and renders nothing; a revised scene renders again', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    const a = await getProductPreview(r.deps, U1, sid, 'canvas:8x8'); const b = await getProductPreview(r.deps, U1, sid, 'canvas:8x8')
    expect(b).toMatchObject({ status: 'ready', cached: true, renderer: 'scene' }); expect(r.sceneRender).toHaveBeenCalledTimes(1); expect(previewFiles(r)).toHaveLength(1)
    r.state.rev = 'scene-rev-2'; const c = await getProductPreview(r.deps, U1, sid, 'canvas:8x8')
    expect((c as any).cached).toBe(false); expect(r.sceneRender).toHaveBeenCalledTimes(2); expect((c as any).url).not.toBe((a as any).url)
  })

  it('a configuration no scene shows uses the calibrated renderer (same product, never a substitute)', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    const v = await getProductPreview(r.deps, U1, sid, 'framed:12x12')           // the framed print's photograph is not approved (frame finish unverified): the calibrated renderer, as before
    expect(v).toMatchObject({ status: 'ready', renderer: 'calibrated', sceneId: null, sku: 'GLOBAL-CFP-12X12', watermarked: true }); expect(r.sceneRender).not.toHaveBeenCalled(); expect(r.render).toHaveBeenCalledTimes(1)
    expect(r.render.mock.calls[0][0]).toMatchObject({ sku: 'GLOBAL-CFP-12X12' })
  })

  it('falls back to the calibrated renderer when the scene cannot render, and never returns a half result', async () => {
    const r = rig(); const { sid } = await withFavorite(r); const log = vi.spyOn(console, 'warn').mockImplementation(() => {}); r.state.sceneFail = true
    expect(await getProductPreview(r.deps, U1, sid, 'canvas:8x8')).toMatchObject({ status: 'ready', renderer: 'calibrated' }); expect(previewFiles(r)).toHaveLength(1); log.mockRestore()
  })

  it('a favorite that is not the product\'s shape returns adaptation_required with the numbers, renders nothing and stores nothing', async () => {
    const r = rig(); const { sid, fav } = await withFavorite(r)
    for (const id of ['fine_art:12x18', 'canvas:12x18', 'framed:12x18']) {
      const v = await getProductPreview(r.deps, U1, sid, id)
      expect(v, id).toMatchObject({ status: 'adaptation_required', reason: 'shape_needs_composition', favoriteId: fav }); expect((v as any).extension).toBeGreaterThan(0.02)
      expect(['deterministic', 'generated', null]).toContain((v as any).method)
    }
    expect(r.sceneRender).not.toHaveBeenCalled(); expect(r.render).not.toHaveBeenCalled(); expect(previewFiles(r)).toHaveLength(0)
  })

  it('a product that is not launched (framed canvas 8x12 on hold, the other card variants) stays not_available: a preview never enables a product', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    for (const id of ['card:7x5-gloss', 'card:7x5-gloss']) expect(await getProductPreview(r.deps, U1, sid, id), id).toMatchObject({ status: 'not_available' })
    expect(r.sceneRender).not.toHaveBeenCalled(); expect(previewFiles(r)).toHaveLength(0)
  })

  it('unknown or unsellable products are not_available, malformed ids are refused, and a favorite must be chosen first', async () => {
    const r = rig(); const v0 = await createSession(r.deps, { userId: U1, imageB64: await photo() })
    await expect(getProductPreview(r.deps, U1, v0.sessionId, 'canvas:8x8')).rejects.toMatchObject({ code: 'artwork_not_selected', status: 409 })
    const { sid } = await withFavorite(r)
    expect(await getProductPreview(r.deps, U1, sid, 'canvas:99x99')).toMatchObject({ status: 'not_available', reason: 'product_not_available', sku: null })
    for (const bad of [undefined, '', 'canvas', '../../x', 'canvas:8x8;drop', 42]) await expect(getProductPreview(r.deps, U1, sid, bad)).rejects.toMatchObject({ code: 'product_not_available' })
  })

  it('is owner-only', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    await expect(getProductPreview(r.deps, U2, sid, 'canvas:8x8')).rejects.toMatchObject({ code: 'session_not_found', status: 404 }); expect(r.sceneRender).not.toHaveBeenCalled()
  })

  it('stored previews are removed with the session', async () => {
    const r = rig(); const { sid } = await withFavorite(r); await getProductPreview(r.deps, U1, sid, 'canvas:8x8'); await getProductPreview(r.deps, U1, sid, 'fine_art:8x8')
    expect(previewFiles(r)).toHaveLength(2)
    await deleteSessionNow(r.deps, U1, sid); expect([...r.files.keys()].filter(k => k.includes(sid))).toEqual([])
  })

  it('without a renderer the endpoint says so (503)', async () => {
    const r = rig(); const { sid } = await withFavorite(r); delete (r.deps as any).mockup
    await expect(getProductPreview(r.deps, U1, sid, 'canvas:8x8')).rejects.toMatchObject({ code: 'mockup_renderer_unavailable', status: 503 })
  })
})

describe('the cart is the server\'s: PUT /lines persists and every later read returns it', () => {
  const L = (lineId: string, productId: string, copies = 1) => ({ lineId, productId, copies })
  it('keeps the gift (product, size, SKU geometry, quantity) across polling, restore and a fresh read, with the favorite', async () => {
    const r = rig(); const { sid, fav } = await withFavorite(r)
    const saved = await setLines(r.deps, U1, sid, [L('a', 'canvas:8x8', 2)])
    expect(saved.lines).toEqual([{ lineId: 'a', productId: 'canvas:8x8', size: '8x8', copies: 2 }])
    const g = saved.geometries[0]; const p = getProduct('canvas:8x8')!
    expect(g).toMatchObject({ lineId: 'a', productId: 'canvas:8x8', sku: p.sku, requiredPx: p.requirements.finalPx })
    for (let i = 0; i < 3; i++) {                                                                  // the generation poll, the batch read and a restore, repeatedly
      expect((await getSessionView(r.deps, U1, sid)).lines).toEqual(saved.lines)
      await getBatchView(r.deps, U1, sid, 1)
      const out = await restoreSession(r.deps, U1)
      expect(out.current!.lines).toEqual(saved.lines); expect(out.current!.artworkPreviewId).toBe(fav); expect(out.resume!.suggestedStep).toBe('cart')
    }
  })

  it('an edit (quantity, size) and a removal persist; an add never drops earlier gifts', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    await setLines(r.deps, U1, sid, [L('a', 'canvas:8x8')])
    await setLines(r.deps, U1, sid, [L('a', 'canvas:8x8', 3), L('b', 'framed:12x18')])
    expect((await restoreSession(r.deps, U1)).current!.lines.map(l => [l.lineId, l.productId, l.copies])).toEqual([['a', 'canvas:8x8', 3], ['b', 'framed:12x18', 1]])
    await setLines(r.deps, U1, sid, [L('b', 'framed:16x24')])
    expect((await getSessionView(r.deps, U1, sid)).lines).toEqual([{ lineId: 'b', productId: 'framed:16x24', size: '16x24', copies: 1 }])
    await setLines(r.deps, U1, sid, [])
    expect((await restoreSession(r.deps, U1)).resume!.suggestedStep).toBe('products')
  })

  it('refuses what is not eligible, leaving the saved cart unchanged: unknown product, bad quantity, duplicate line, another customer\'s session', async () => {
    const r = rig(); const { sid } = await withFavorite(r); await setLines(r.deps, U1, sid, [L('a', 'canvas:8x8')])
    await expect(setLines(r.deps, U1, sid, [L('x', 'canvas:99x99')])).rejects.toMatchObject({ code: 'product_not_available' })
    await expect(setLines(r.deps, U1, sid, [L('x', 'canvas:8x8', 0)])).rejects.toMatchObject({ code: 'invalid_quantity' })
    await expect(setLines(r.deps, U1, sid, [L('x', 'canvas:8x8', 99)])).rejects.toMatchObject({ code: 'invalid_quantity' })
    await expect(setLines(r.deps, U1, sid, [L('x', 'canvas:8x8'), L('x', 'framed:12x18')])).rejects.toMatchObject({ code: 'duplicate_line' })
    await expect(setLines(r.deps, U2, sid, [L('a', 'canvas:8x8')])).rejects.toMatchObject({ code: 'session_not_found' })
    expect((await getSessionView(r.deps, U1, sid)).lines).toEqual([{ lineId: 'a', productId: 'canvas:8x8', size: '8x8', copies: 1 }])
  })

  it('price is never taken from the client: a line carries no price, and the catalog (not the request) decides the total at checkout', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    const saved = await setLines(r.deps, U1, sid, [{ ...L('a', 'canvas:8x8'), retailCents: 1, price: 1, sku: 'FAKE-SKU' } as any])
    expect(saved.lines[0]).toEqual({ lineId: 'a', productId: 'canvas:8x8', size: '8x8', copies: 1 })
    expect(saved.geometries[0].sku).toBe(getProduct('canvas:8x8')!.sku)
  })
})

describe('provisional preview for a favorite whose shape is not the product\'s (opt-in)', () => {
  it('without the flag the answer is still adaptation_required (existing clients are not surprised)', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    expect(await getProductPreview(r.deps, U1, sid, 'fine_art:12x18')).toMatchObject({ status: 'adaptation_required' })
    expect(r.render).not.toHaveBeenCalled(); expect(previewFiles(r)).toHaveLength(0)
  })

  it('with the flag it shows the WHOLE favorite in the product on a neutral surround, says it is provisional, and says what the real composition will do', async () => {
    const r = rig(); const { sid, fav } = await withFavorite(r)
    const before = JSON.stringify(await getSessionView(r.deps, U1, sid)), compBefore = r.store.compositions.length, gens = r.generate.mock.calls.length
    const v: any = await getProductPreview(r.deps, U1, sid, 'fine_art:12x18', { provisional: true })
    expect(v).toMatchObject({ status: 'provisional', productId: 'fine_art:12x18', sku: 'GLOBAL-FAP-12X18', favoriteId: fav, renderer: 'scene', sceneId: 'fine-art-portrait', sceneRefusal: null, fit: 'contain', watermarked: true, productionPrintFile: false, purchaseAuthorization: false, cached: false })
    expect(v.provisional).toMatchObject({ exactArtworkShown: true, cropped: false, distorted: false, surround: 'neutral', finalComposition: 'generated' })
    expect(v.provisional.bars.sides).toBe('top_bottom'); expect(v.provisional.bars.fractionPerSide).toBeCloseTo(1 / 6, 3)          // a square favorite in a 2:3 product: a sixth of the height above and below
    expect(v.provisional.extension).toBeCloseTo(0.5, 3); expect(v.url).toMatch(/\/product-previews\/fine_art_12x18-[0-9a-f]{16}\.jpg/)
    expect(r.sceneRender).toHaveBeenCalledTimes(1); expect(r.render).not.toHaveBeenCalled(); expect(previewFiles(r)).toHaveLength(1)
    expect(r.store.compositions.length).toBe(compBefore); expect(r.generate.mock.calls.length).toBe(gens)                          // no composition, no generation
    expect(JSON.stringify(await getSessionView(r.deps, U1, sid))).toBe(before)                                                      // approvals, corrections, entitlements untouched
    const again: any = await getProductPreview(r.deps, U1, sid, 'fine_art:12x18', { provisional: true }); expect(again).toMatchObject({ status: 'provisional', cached: true }); expect(r.sceneRender).toHaveBeenCalledTimes(1)
  })

  it('the picture handed to the renderer is the favorite, undistorted and uncropped, centered, with only the surround added (never mirrored, never artwork-colored)', async () => {
    const { containedPicture, PROVISIONAL_SURROUND } = await import('./product-preview')
    const art = await sharp({ create: { width: 800, height: 800, channels: 3, background: '#d02020' } }).composite([{ input: await sharp({ create: { width: 200, height: 200, channels: 3, background: '#2020d0' } }).png().toBuffer(), left: 0, top: 0 }]).png().toBuffer()
    const out = await containedPicture(art, getProduct('fine_art:12x18')!)
    const m = await sharp(out.picture).metadata(); expect(Math.abs(m.width! / m.height! - 2 / 3)).toBeLessThan(0.002)
    expect(out.bars.sides).toBe('top_bottom')
    const raw = await sharp(out.picture).removeAlpha().raw().toBuffer(), px = (x: number, y: number) => [...raw.subarray((y * m.width! + x) * 3, (y * m.width! + x) * 3 + 3)]
    const hex = (c: number[]) => '#' + c.map(n => n.toString(16).padStart(2, '0')).join('')
    expect(hex(px(5, 5))).toBe(PROVISIONAL_SURROUND); expect(hex(px(m.width! - 5, m.height! - 5))).toBe(PROVISIONAL_SURROUND)          // the bars are the neutral surround, not a reflection of the art
    const top = Math.floor((m.height! - m.width!) / 2)                                                                              // the art is exactly square, full width, centered
    expect(hex(px(5, top + 5))).toBe('#2020d0'); expect(hex(px(m.width! - 5, top + 5))).toBe('#d02020'); expect(hex(px(5, top + m.width! - 5))).toBe('#d02020')
    expect(hex(px(5, top - 3))).toBe(PROVISIONAL_SURROUND)
  })

  it('a favorite already within 2% of the product is unaffected by the flag: an ordinary ready preview', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    expect(await getProductPreview(r.deps, U1, sid, 'canvas:8x8', { provisional: true })).toMatchObject({ status: 'ready', renderer: 'scene' })
  })

  it('unlaunched products stay not_available with the flag, and the owner check still applies', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    expect(await getProductPreview(r.deps, U1, sid, 'card:7x5-gloss', { provisional: true })).toMatchObject({ status: 'not_available' })
    await expect(getProductPreview(r.deps, U2, sid, 'fine_art:12x18', { provisional: true })).rejects.toMatchObject({ code: 'session_not_found' })
  })

  it('the provisional picture uses the scene renderer where a photograph truthfully shows the configuration, with the same fixed inset (canvas portrait has none: calibrated)', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    expect(await getProductPreview(r.deps, U1, sid, 'canvas:12x18', { provisional: true })).toMatchObject({ status: 'provisional', renderer: 'calibrated' })
    expect(r.sceneRender).not.toHaveBeenCalled()
  })
})

describe('the preview says why it is not scene-backed', () => {
  it('fine art 8x8: ready through the calibrated renderer with the measured refusal; the square canvas has none', async () => {
    const r = rig(); const { sid } = await withFavorite(r)
    const opening = realSceneRenderer.describe('fine-art-square').inputAspect, ext = Math.max(opening, 1 / opening) - 1
    const fa = await getProductPreview(r.deps, U1, sid, 'fine_art:8x8')
    if (ext <= 0.02 + 1e-10) expect(fa).toMatchObject({ status: 'ready', renderer: 'scene', sceneRefusal: null })
    else expect(fa).toMatchObject({ status: 'ready', renderer: 'calibrated', sceneRefusal: { reason: 'shape_needs_extension', sceneId: 'fine-art-square', openingAspect: Math.round(opening * 1e4) / 1e4, extension: Math.round(ext * 1e4) / 1e4 } })
    expect(await getProductPreview(r.deps, U1, sid, 'canvas:8x8')).toMatchObject({ renderer: 'scene', sceneRefusal: null })
    expect(await getProductPreview(r.deps, U1, sid, 'canvas:12x18', { provisional: true })).toMatchObject({ status: 'provisional', sceneRefusal: { reason: 'shape_needs_extension' } })
  })
})
